#include <algorithm>
#include <climits>
#include <stdexcept>
#include <vector>

class Fenwick
{
public:
    explicit Fenwick(std::size_t n) : t_(n + 1, 0) {}

    void add(std::size_t i, long long delta)
    {
        for (std::size_t k = i + 1; k < t_.size(); k += k & (~k + 1)) t_[k] += delta;
    }

    long long prefix(std::size_t count) const
    {
        long long s = 0;
        for (std::size_t k = count; k > 0; k -= k & (~k + 1)) s += t_[k];
        return s;
    }

    long long sum(std::size_t l, std::size_t r) const { return prefix(r + 1) - prefix(l); }

    std::size_t lowerBound(long long target) const
    {
        if (target <= 0) return 0;
        std::size_t n = t_.size() - 1, pos = 0, step = 1;
        while (step * 2 <= n) step *= 2;
        for (; step > 0; step /= 2)
            if (pos + step <= n && t_[pos + step] < target)
            {
                pos += step;
                target -= t_[pos];
            }
        return pos + 1;          // n + 1 when the whole sum is below the target
    }

private:
    std::vector<long long> t_;
};

class MaxTree
{
public:
    explicit MaxTree(const std::vector<int>& a) : n_(a.size()), t_(2 * a.size(), INT_MIN)
    {
        for (std::size_t i = 0; i < n_; ++i) t_[n_ + i] = a[i];
        for (std::size_t i = n_; i-- > 1;) t_[i] = std::max(t_[2 * i], t_[2 * i + 1]);
    }

    void set(std::size_t i, int value)
    {
        if (i >= n_) throw std::out_of_range("set");
        for (t_[i += n_] = value; i > 1; i /= 2) t_[i / 2] = std::max(t_[i], t_[i ^ 1]);
    }

    int max(std::size_t l, std::size_t r) const
    {
        if (l > r || r >= n_) throw std::out_of_range("max");
        int best = INT_MIN;
        for (std::size_t lo = l + n_, hi = r + n_ + 1; lo < hi; lo /= 2, hi /= 2)    // the bottom-up form
        {
            if (lo & 1) best = std::max(best, t_[lo++]);
            if (hi & 1) best = std::max(best, t_[--hi]);
        }
        return best;
    }

private:
    std::size_t n_;
    std::vector<int> t_;
};

long long countInversionsFenwick(const std::vector<int>& a)
{
    std::vector<int> sorted(a);
    std::sort(sorted.begin(), sorted.end());
    sorted.erase(std::unique(sorted.begin(), sorted.end()), sorted.end());
    Fenwick seen(sorted.size());
    long long count = 0;
    for (std::size_t i = a.size(); i-- > 0;)
    {
        std::size_t r = static_cast<std::size_t>(std::lower_bound(sorted.begin(), sorted.end(), a[i]) - sorted.begin());
        count += seen.prefix(r);         // values already seen to the right that are smaller
        seen.add(r, 1);
    }
    return count;
}

unitTests:
#include <random>

TEST("prefix and range sums") {
    Fenwick f(10);
    int v[] = { 5, 3, 7, 9, 6, 4, 1, 2, 8, 10 };
    for (std::size_t i = 0; i < 10; ++i) f.add(i, v[i]);
    CHECK_EQ(f.prefix(0), 0LL);
    CHECK_EQ(f.prefix(3), 15LL);
    CHECK_EQ(f.prefix(10), 55LL);
    CHECK_EQ(f.sum(2, 5), 26LL);
    CHECK_EQ(f.sum(9, 9), 10LL);
    f.add(4, 100);
    CHECK_EQ(f.sum(2, 5), 126LL);
    f.add(0, -5);
    CHECK_EQ(f.prefix(1), 0LL);
}
TEST("finding a prefix by its sum") {
    Fenwick f(8);
    int v[] = { 2, 0, 3, 1, 0, 0, 4, 1 };                  // prefix sums 2 2 5 6 6 6 10 11
    for (std::size_t i = 0; i < 8; ++i) f.add(i, v[i]);
    CHECK_EQ(f.lowerBound(0), std::size_t{ 0 });
    CHECK_EQ(f.lowerBound(1), std::size_t{ 1 });
    CHECK_EQ(f.lowerBound(2), std::size_t{ 1 });
    CHECK_EQ(f.lowerBound(3), std::size_t{ 3 });
    CHECK_EQ(f.lowerBound(6), std::size_t{ 4 });
    CHECK_EQ(f.lowerBound(7), std::size_t{ 7 });
    CHECK_EQ(f.lowerBound(11), std::size_t{ 8 });
    CHECK_EQ(f.lowerBound(12), std::size_t{ 9 });
    Fenwick g(5);
    g.add(2, 1);
    CHECK_EQ(g.lowerBound(1), std::size_t{ 3 });
}
TEST("range maximum") {
    MaxTree t({ 12, 9, 15, 7, 11, 14, 8, 10 });
    CHECK_EQ(t.max(0, 7), 15);
    CHECK_EQ(t.max(3, 6), 14);
    CHECK_EQ(t.max(3, 3), 7);
    t.set(2, 1);
    CHECK_EQ(t.max(0, 3), 12);
    t.set(7, 99);
    CHECK_EQ(t.max(5, 7), 99);
    CHECK_THROWS(t.max(4, 3));
    CHECK_THROWS(t.max(0, 8));
    MaxTree odd({ -5, -2, -9 });
    CHECK_EQ(odd.max(0, 2), -2);
    CHECK_EQ(odd.max(2, 2), -9);
}
TEST("100,000 mixed operations") {
    const std::size_t n = 100000;
    std::vector<int> a(n);
    std::mt19937 rng(8);
    for (auto& x : a) x = static_cast<int>(rng() % 1000);
    Fenwick f(n);
    for (std::size_t i = 0; i < n; ++i) f.add(i, a[i]);
    MaxTree m(a);
    bool ok = true;
    for (int step = 0; step < 100000; ++step)
    {
        std::size_t i = rng() % n;
        int v = static_cast<int>(rng() % 1000);
        f.add(i, v - a[i]);
        m.set(i, v);
        a[i] = v;
        std::size_t l = rng() % n, r = rng() % n;
        if (l > r) std::swap(l, r);
        if (step % 10000 == 0)
        {
            long long s = 0;
            int mx = -1;
            for (std::size_t k = l; k <= r; ++k) { s += a[k]; mx = std::max(mx, a[k]); }
            ok = ok && f.sum(l, r) == s && m.max(l, r) == mx;
        }
        else
        {
            ok = ok && f.sum(l, r) >= 0 && m.max(l, r) >= 0;
        }
    }
    CHECK(ok);
}
TEST("inversions with a Fenwick tree") {
    CHECK_EQ(countInversionsFenwick({ 2, 4, 1, 3, 5 }), 3LL);
    CHECK_EQ(countInversionsFenwick({ 8, 3, 9, 1, 1, 7, 2, 6, 6, 0 }), 28LL);
    CHECK_EQ(countInversionsFenwick({ 1000000000, -1000000000, 0 }), 2LL);
    CHECK_EQ(countInversionsFenwick({}), 0LL);
    std::vector<int> rev(100000);
    for (int i = 0; i < 100000; ++i) rev[i] = 100000 - i;
    CHECK_EQ(countInversionsFenwick(rev), 4999950000LL);
}

